#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Section MovingMidpointTrapezoid. Variable R : realType. Variables (A B : 'rV[R]_2). Hypothesis HAB : A <> B. Variable d : 'rV[R]_2. Hypothesis d_nonzero : d != 0. Hypothesis d_parallel_AB : exists k : R, d = k *: (B - A). Variable Q : 'rV[R]_2. Variable P : R -> 'rV[R]_2. Hypothesis P_def : forall t : R, P t = Q + t *: d. Definition M (t : R) : 'rV[R]_2 := (P t + A) / 2%:R. Definition N (t : R) : 'rV[R]_2 := (P t + B) / 2%:R. Definition MN_length (t : R) := normr (N t - M t). Definition perimeter_PAB (t : R) := normr (P t - A) + normr (P t - B) + normr (B - A). Theorem monotonic_mid_length : forall t1 t2 : R, t1 < t2 -> MN_length t1 <= MN_length t2. Proof. Admitted. End
